DELETE FROM products;
INSERT INTO products (id, name, price, description, short_description, variants, images, local_img, in_stock) VALUES ('kaleidoscope', 'KALEIDOSKOP filtr', '990 Kč', '
    <div>
        <div class="product-detail-grid">
            <div style="grid-column: 1 / -1; margin-bottom: -20px;">
                <h4><span style="color: var(--color-accent)">Detailní</span> popis produktu</h4>
            </div>
            <div class="desc-col-left">
                <p>Hledáte způsob, jak svému vizuálu vdechnout neotřelou dynamiku a vymanit se z nudné reality? Fotografický filtr <strong style="color: var(--color-accent)">KALEIDOSKOP</strong> je vytvořený pro odvážné tvůrce, kteří se nebojí experimentovat. Tento prémiový filtr doslova tříští realitu do geometrické exploze, kde se středový obraz zachovává ostrý, zatímco jeho okraje se abstraktně replikují po obvodu. Výsledkem je podmanivý vizuální efekt připomínající snovou mandalu, který dodá vašim portrétům, nočním scénám i hudebním klipům naprosto <strong style="color: var(--color-accent)">jedinečný psychedelický charakter</strong>.</p>
            </div>
            <div class="desc-col-right">
                <p>Tajemství tohoto uhrančivého efektu spočívá v samotné konstrukci. Základem filtru je <strong style="color: var(--color-accent)">precizně broušené optické sklo</strong> s několika lomenými plochami pod pečlivě vypočítanými úhly. Filtr je navíc usazen v hladce otočné obroučce, takže můžete během okamžiku měnit pozici a směr replikovaných obrazů v reálném čase. Ať už fotíte neony nočního města nebo artový portrét s otevřenou clonou, Kaleidoskop promění i tu nejobyčejnější scénu ve fascinující umělecké dílo.</p>
            </div>
        </div>
    </div>
    ', 'Geometrická exploze obrazu pro odvážnou tvorbu. Využívá precizně broušené optické sklo.', '["77mm","82mm"]', '["images/kaleidoscope_0.png","assets/filters/kaleidoscope-1.jpg","assets/filters/kaleidoscope-2.jpg"]', 'images/kaleidoscope_0.png', 1);
INSERT INTO products (id, name, price, description, short_description, variants, images, local_img, in_stock) VALUES ('fog', 'FOG filtr', '990 Kč', '
    <div>
        <div class="product-detail-grid">
            <div style="grid-column: 1 / -1; margin-bottom: -20px;">
                <h4><span style="color: var(--color-accent)">Detailní</span> popis produktu</h4>
            </div>
            <div class="desc-col-left">
                <p >Toužíte do svých snímků vnést nefalšovanou snovou atmosféru, kterou znáte z klasických celuloidových filmů? Fotografický filtr <strong style="color: var(--color-accent)">FOG</strong> je nepostradatelným nástrojem pro kreativní tvůrce, kteří chtějí vystoupit z řady dokonale ostrých, ale často chladných a příliš technických digitálních záběrů. Tento prémiový filtr jemně rozostřuje dopadající světlo a citlivě zjemňuje mikro-detaily. Výsledkem je podmanivý, něžný a hluboce romantický efekt, který povýší každou fotografii na umělecké dílo – to vše <strong style="color: var(--color-accent)">bez jakékoliv ztráty žádoucího kontrastu nebo hloubky černé</strong>.</p>
            </div>
            <div class="desc-col-right">
                <p >Tajemství dokonalého výsledku spočívá v samotné konstrukci. Základem filtru FOG je <strong style="color: var(--color-accent)">špičkové optické sklo nejvyšší jakosti</strong>, v jehož vnitřní struktuře jsou s absolutní precizností rovnoměrně rozprostřeny tisíce mikroskopických částic. Tyto částice fungují jako sofistikovaná, oku neviditelná síť. Jakmile skrze ně prochází světlo, jemně se láme a rozptyluje, což snímkům dodává přirozený organický nádech, který v postprocesu jen stěží napodobíte.</p>
            </div>
        </div>
    </div>
    ', 'Rozostřuje dopadající světlo a zjemňuje detaily pro klasický filmový vzhled bez ztráty kontrastu.', '["77mm","82mm"]', '["images/fog_0.png","assets/filters/fog-1.jpg"]', 'images/fog_0.png', 1);
INSERT INTO products (id, name, price, description, short_description, variants, images, local_img, in_stock) VALUES ('halo', 'HALO filtr', '990 Kč', '
    <div>
        <div class="product-detail-grid">
            <div style="grid-column: 1 / -1; margin-bottom: -20px;">
                <h4><span style="color: var(--color-accent)">Detailní</span> popis produktu</h4>
            </div>
            <div class="desc-col-left">
                <p>Přejete si okamžitě připoutat divákovu pozornost k hlavnímu objektu a zároveň zachovat silnou filmovou estetiku? Fotografický filtr <strong style="color: var(--color-accent)">HALO</strong> vytváří magický prstenec světla, který přirozeně a elegantně izoluje váš subjekt. Zatímco střed snímku zůstává krystalicky čistý a ostrý, okraje se jemně rozmývají do dynamického pohybu připomínajícího tunelové vidění. Je to perfektní volba pro street fotografii, akční záběry nebo fashion portréty, kde potřebujete vystoupit z davu a dodat fotce <strong style="color: var(--color-accent)">organickou hloubku a analogový nádech</strong>.</p>
            </div>
            <div class="desc-col-right">
                <p>Kouzlo filtru HALO spočívá ve <strong style="color: var(--color-accent)">speciálně tvarovaném optickém skle s radiálními fazetami</strong>. Tato unikátní optická deformace nejenže soustředí pohled do středu, ale při střetu s protisvětlem dokáže v prstenci vytvořit jemné duhové odlesky a sytý barevný opar. Při použití nižšího clonového čísla (f/1.8 – f/2.8) se přechod mezi ostrým středem a snovým okrajem stává neuvěřitelně plynulým, což posouvá vaše snímky i videa na úroveň profesionální filmové produkce.</p>
            </div>
        </div>
    </div>
    ', 'Magický prstenec světla, který přirozeně vede oko diváka přímo do středu kompozice.', '["77mm","82mm"]', '["images/halo_0.jpg","assets/filters/halo-1.jpg","assets/filters/halo-2.jpg"]', 'images/halo_0.jpg', 1);

DELETE FROM blog;
INSERT INTO blog (id, title, slug, image, text, content, date, meta_title, meta_desc, keywords) VALUES ('1', 'Jak ovládnout lom světla s Prism filtrem', 'jak-ovladnout-lom-svetla-s-prism-filtrem', 'https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?auto=format&fit=crop&w=600&q=80', 'Praktické tipy pro nastavení clony a úhlu záběru, kterými docílíte nejkrásnějších duhových odlesků bez přeexponování scény.', '<p>Prism filtry zažívají obrovský návrat do výbavy profesionálních filmařů a fotografů. Díky jejich schopnosti lámat světelné paprsky a tvořit analogové, snové artefakty přímo v objektivu dodávají digitálnímu obrazu tolik chybějící charakter.</p><h3>Výběr správného ohniska</h3><p>Nejlepší výsledky s Prism filtry (např. typ Kaleidoscope nebo Linear Prism) získáte s objektivy s delší ohniskovou vzdáleností. <strong>Doporučujeme rozmezí 50mm až 85mm.</strong> Širokoúhlé objektivy mají tendenci zabrat filtr samotný nebo vytvářejí příliš drobný efekt, který se ztratí v celkové kompozici.</p><h3>Práce s clonou</h3><p>Čím otevřenější clonu použijete (např. f/1.4 nebo f/1.8), tím více se efekt ''rozpije'' a změkne. Vzniknou plynulé, snové přechody. Pokud potřebujete ostřejší rozdělení hranolů, zkuste přiclonit na f/4 až f/5.6.</p><h3>Světelné zdroje</h3><p>Tajemství úspěchu spočívá v přímém protisvětle. Postavte fotografovaný objekt před silný světelný zdroj (Slunce, reflektor, neonové trubice) a mírně pootáčejte filtrem v závitu. Právě pohybem filtru měníte úhel dopadu světla na hranol a tvoříte úchvatné duhové fléry přesně tam, kde je v obraze chcete mít.</p><img src=''https://images.unsplash.com/photo-1542038784456-1ea8e935640e?auto=format&fit=crop&w=800&q=80'' alt=''Ukázka z natáčení'' style=''width: 100%; border-radius: 12px; margin: 30px 0;''><p>Experimentujte! Každé pootočení přinese zcela nový, neopakovatelný výsledek.</p>', 'TUTORIÁL • 5 MIN ČTENÍ', '', '', '');
INSERT INTO blog (id, title, slug, image, text, content, date, meta_title, meta_desc, keywords) VALUES ('2', 'Proč filmaři milují difuzní filtry (Fog look)', 'proc-filmari-miluji-difuzni-filtry-fog-look', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=600&q=80', 'Pohled do zákulisí nezávislých filmů. Jak Fog filtr pomáhá simulovat anamorfní optiku na běžných digitálních objektivech.', '<p>V éře ultra-ostrých digitálních senzorů a 8K rozlišení hledají kameramani způsoby, jak obraz ''změkčit'' a dodat mu kinematografický, analogový nádech. A právě zde vstupují na scénu difuzní filtry (např. Black Mist, Fog, nebo Glimmerglass).</p><h3>Halace světel</h3><p>Hlavním efektem difuzních filtrů je tzv. <em>halation</em>, tedy rozptýlení světla kolem jasných zdrojů. Praktické žárovky, pouliční lampy nebo slunce za oknem získají nádhernou, organickou záři (glow), která napodobuje staré filmové materiály a klasické hollywoodské objektivy.</p><h3>Zjemnění pleti</h3><p>Kromě světelné halace tyto filtry jemně snižují lokální kontrast ve středních tónech. Pro portrétní fotografii a beauty záběry to znamená jediné: automatické vyhlazení nedokonalostí pleti bez ztráty detailů v očích nebo vlasech. Ušetříte tak desítky hodin retušování v postprodukci.</p><h3>Jakou sílu zvolit?</h3><p>Filtry se prodávají v různých stupních síly (např. 1/8, 1/4, 1/2, 1). Pro běžné natáčení a focení doporučujeme začít s hodnotou <strong>1/4</strong>. Dodá obrazu charakter, ale zachová ostrost. Sílu 1/2 a 1 používejte pro snové sekvence, hudební videoklipy nebo silně stylizované retro portréty.</p><p>Difuzní filtr by neměl chybět v brašně žádného tvůrce, který usiluje o filmový look bez nutnosti kupovat objektivy za statisíce korun.</p>', 'INSPIRACE • 8 MIN ČTENÍ', '', '', '');
